import test from 'node:test';import assert from 'node:assert/strict';
import {newAfternoonScenario,save,restore} from './simulation.js';
import {beginPersonalEvent,progressPersonalEvent,pausePersonalEvent,personalEventsAt} from './personal-events.js';
import {nursingStudentLocation} from './nursing-student-events.js';
import {personalEventPosition} from './personal-event-presence.js';
import {advanceFreeTime} from './free-roam.js';
import {displayName,presentationText} from './identity.js';
import {knownCharacterAge} from './character-profiles.js';
import {eventCutscene} from './event-cutscenes.js';
function ready(){const s=newAfternoonScenario('close');s.clock.minute=840;s.location='library';return s;}
function complete(){let s=beginPersonalEvent(ready(),'nursing-student:book');s=progressPersonalEvent(s,'ask');return progressPersonalEvent(s,'leave');}
test('new student meets through a real book mix-up without inventing a name or friendship',()=>{let s=beginPersonalEvent(ready(),'nursing-student:book');assert.match(displayName(s,'nursingStudent'),/안경테/);assert.equal(knownCharacterAge(s,'nursingStudent'),null);s=progressPersonalEvent(s,'ask');assert.equal(s.contacts.nursingStudent.introduced,false);assert.equal(s.contacts.nursingStudent.details.major,'간호학과');assert.equal(knownCharacterAge(s,'nursingStudent'),22);assert.match(s.personalEvents.records['nursing-student:book'].last.text,/스물두/);assert.equal(presentationText(s,'학생회관에 학생이 있다.'),'자유관에 학생이 있다.');});
test('both steps consume real time once, survive saving and leave an independently completed record',()=>{let s=beginPersonalEvent(ready(),'nursing-student:book');const before=save(s);s=progressPersonalEvent(s,'check');assert.equal(s.clock.minute,850);s=restore(save(s));assert.deepEqual(s.personalEvents.records['nursing-student:book'].choices,['check']);s=progressPersonalEvent(s,'mark');assert.equal(s.clock.minute,870);assert.equal(s.personalEvents.records['nursing-student:book'].status,'completed');assert.throws(()=>progressPersonalEvent(s,'mark'));assert.notEqual(save(s),before);assert.ok(!personalEventsAt(s).some(e=>e.eventId==='nursing-student:book'));});
test('cafe follow-up needs the earlier real meeting and a later day at the actual cafe',()=>{let s=ready();s.clock.minute=960;s.location='cafe';assert.throws(()=>beginPersonalEvent(s,'nursing-student:break'));s=complete();s.clock.minute=960;s.location='cafe';assert.throws(()=>beginPersonalEvent(s,'nursing-student:break'));s.day=2;s.location='hall';assert.throws(()=>beginPersonalEvent(s,'nursing-student:break'));s.location='cafe';const first=save(s.personalEvents.records['nursing-student:book']);s=progressPersonalEvent(beginPersonalEvent(s,'nursing-student:break'),'rest');s=progressPersonalEvent(restore(save(s)),'quiet');assert.equal(s.clock.minute,990);assert.equal(save(s.personalEvents.records['nursing-student:book']),first);assert.equal(s.personalEvents.records['nursing-student:break'].status,'completed');});
test('pausing, leaving and expiry release the student and cannot grant stale event results',()=>{let s=progressPersonalEvent(beginPersonalEvent(ready(),'nursing-student:book'),'check');assert.equal(personalEventPosition(s,'nursingStudent'),'library');let paused=pausePersonalEvent(s);assert.equal(personalEventPosition(paused,'nursingStudent'),null);assert.deepEqual(paused.personalEvents.records['nursing-student:book'].choices,['check']);const moved=structuredClone(s);moved.location='hall';assert.equal(personalEventPosition(moved,'nursingStudent'),null);assert.throws(()=>progressPersonalEvent(moved,'mark'));const expired=advanceFreeTime(s,21);assert.equal(expired.personalEvents.active,null);assert.equal(expired.personalEvents.records['nursing-student:book'].status,'paused');assert.throws(()=>progressPersonalEvent(expired,'leave'));paused.clock.minute=960;assert.equal(nursingStudentLocation(paused),'cafe');});
test('two matching CGs follow real scene/day/place/participant bounds and disappear after completion',()=>{let s=beginPersonalEvent(ready(),'nursing-student:book');const before=save(s),beat={kind:'speech',actor:'nursingStudent'};assert.equal(eventCutscene(s,'personalEvent',beat).id,'nursing-library');assert.equal(eventCutscene(s,'personalEvent',{kind:'speech',actor:'taei'}),null);assert.equal(save(s),before);const wrong=structuredClone(s);wrong.location='hall';assert.equal(eventCutscene(wrong,'personalEvent',beat),null);s=progressPersonalEvent(s,'check');s=progressPersonalEvent(s,'leave');assert.equal(eventCutscene(s,'personalEvent',beat),null);s.day=2;s.clock.minute=960;s.location='cafe';s=beginPersonalEvent(s,'nursing-student:break');assert.equal(eventCutscene(s,'personalEvent',beat).id,'nursing-rest');});

test('Jian reveals her chosen name only through a spoken introduction, including a later closing introduction',()=>{
 for(const first of ['names','check']){let s=beginPersonalEvent(ready(),'nursing-student:book');assert.notEqual(displayName(s,'nursingStudent'),'백지안');s=progressPersonalEvent(s,first);if(first==='names'){assert.equal(displayName(s,'nursingStudent'),'백지안');assert.throws(()=>progressPersonalEvent(s,'names'));s=progressPersonalEvent(s,'leave');}else s=progressPersonalEvent(s,'names');assert.equal(displayName(s,'nursingStudent'),'백지안');assert.equal(s.contacts.nursingStudent.details.age,22);assert.equal(s.personalEvents.records['nursing-student:book'].status,'completed');}
});
